def index_sections(lines):
    outline = build_outline(lines)
    if isinstance(outline, dict):
        return outline
    entries = []
    work = [(outline, "")]
    pos = 0
    while pos < len(work):
        nodes, prefix = work[pos]
        pos += 1
        ordinal = 0
        while ordinal < len(nodes):
            node = nodes[ordinal]
            ordinal += 1
            if node["level"] > 3:
                continue
            if prefix == "":
                number = str(ordinal)
            else:
                number = prefix + "." + str(ordinal)
            entries.append({"number": number, "title": node["title"]})
            work.append((node["children"], number))
    return entries

